question:
What is the output of the following code?

let x = 5;
console.log(x++);

What does the following arrow function return?

const double = x => x * 2;
console.log(double(7));

What will the following code log?

const arr = [1, 2, 3];
console.log(arr.map(n => n * n));

What is the output?

const obj = { a: 1 };
const copy = Object.assign({}, obj);
copy.a = 99;
console.log(obj.a);

What does the following code output?

function* gen() {
  yield 1;
  yield 2;
  yield 3;
}
const g = gen();
console.log(g.next().value);

What is the output of the following closure example?

function makeCounter() {
  let count = 0;
  return () => ++count;
}
const c1 = makeCounter();
const c2 = makeCounter();
c1(); c1();
console.log(c2());

Consider this JavaScript code:

const a = [1, 2, 3];
const b = a;
b.push(4);
console.log(a.length);

What is the output of this advanced async code?

async function foo() {
  return 42;
}
async function bar() {
  const result = await foo();
  console.log(result);
}
bar();

What does the following code log?

function outer() {
  let x = 10;
  function inner() { console.log(x); }
  x = 20;
  inner();
}
outer();

What is the output order of this code?

console.log('A');
setTimeout(() => console.log('B'), 0);
Promise.resolve().then(() => console.log('C'));
console.log('D');
